import{c as t,Q as l,j as i,m as a}from"./chunks/framework.BPKcPtvA.js";const p=JSON.parse('{"title":"术语表 - Hyperliquid 与 Web3 资产找回专业词汇","description":"为你科普高风险地址受限相关的专业术语，包括 flagged address（标记地址）、Arbitrum L2、L1 结算、未授权状态及服务费。","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://hyperliquidrecoverybot.github.io/zh/glossary"}],["link",{"rel":"alternate","hreflang":"en","href":"https://hyperliquidrecoverybot.github.io/en/glossary"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://hyperliquidrecoverybot.github.io/zh/glossary"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://hyperliquidrecoverybot.github.io/en/glossary"}],["meta",{"name":"keywords","content":"DeFi专业术语, 资产找回概念, 风险地址定义, 区块链名词解释"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"术语表 - Hyperliquid 与 Web3 资产找回专业词汇"}],["meta",{"property":"og:description","content":"为你科普高风险地址受限相关的专业术语，包括 flagged address（标记地址）、Arbitrum L2、L1 结算、未授权状态及服务费。"}],["meta",{"property":"og:url","content":"https://hyperliquidrecoverybot.github.io/zh/glossary"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"术语表 - Hyperliquid 与 Web3 资产找回专业词汇"}],["meta",{"name":"twitter:description","content":"为你科普高风险地址受限相关的专业术语，包括 flagged address（标记地址）、Arbitrum L2、L1 结算、未授权状态及服务费。"}]]},"headers":[],"relativePath":"zh/glossary.md","filePath":"zh/glossary.md","lastUpdated":null}'),o={name:"zh/glossary.md"};function r(d,e,c,n,s,h){return l(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><p>本页解释您在检测和恢复过程中可能看到的常见术语。</p><h2 id="费用相关" tabindex="-1">费用相关 <a class="header-anchor" href="#费用相关" aria-label="Permalink to &quot;费用相关&quot;">​</a></h2><ul><li><code>Service Fee</code>：服务费，恢复价值的 0.5%，最低 1 USDC。</li><li><code>Withdrawal Fees</code>：提现手续费，Hyperliquid 每次提现 1 USDC，通常共 2 USDC。</li><li><code>Total Cost</code>：总成本，<code>Service Fee + Withdrawal Fees</code>。</li><li><code>You Will Receive</code>：用户预计/实际到账金额。</li></ul><h2 id="账户与资产" tabindex="-1">账户与资产 <a class="header-anchor" href="#账户与资产" aria-label="Permalink to &quot;账户与资产&quot;">​</a></h2><ul><li><code>SPOT</code>：现货账户中的普通代币余额。</li><li><code>PERP</code>：与永续交易相关的余额或持仓。</li><li><code>VAULT</code>：存放在金库中的资产，其中部分资产可能暂时处于锁定状态。</li><li><code>STAKED</code>：处于质押相关状态的 HYPE 余额。</li></ul><h2 id="质押状态" tabindex="-1">质押状态 <a class="header-anchor" href="#质押状态" aria-label="Permalink to &quot;质押状态&quot;">​</a></h2><ul><li><code>HYPE-STAKED</code>：HYPE 仍处于质押中，暂时不能立即提现。</li><li><code>HYPE-UNSTAKED</code>：HYPE 已离开主动质押阶段，可进入后续处理流程。</li><li><code>HYPE-PENDING</code>：已发起提取，但仍处于等待期。</li></ul><h2 id="步骤级状态" tabindex="-1">步骤级状态 <a class="header-anchor" href="#步骤级状态" aria-label="Permalink to &quot;步骤级状态&quot;">​</a></h2><ul><li><code>completed</code>：这一步已经成功完成。</li><li><code>completed_partial</code>：这一步只完成了一部分，仍可能有资产需要后续处理。</li><li><code>completed_waiting</code>：这一步已完成，但下一步需要先等待。</li><li><code>skipped_locked</code>：这一步被跳过，因为相关资产当前处于锁定状态。</li><li><code>skipped_no_assets</code>：这一步被跳过，因为当前没有可处理资产。</li><li><code>failed_*</code>：这一步执行失败，原因可能是系统、输入或网络问题。</li></ul><h2 id="任务级终态" tabindex="-1">任务级终态 <a class="header-anchor" href="#任务级终态" aria-label="Permalink to &quot;任务级终态&quot;">​</a></h2><ul><li><code>completed</code>：本轮已有实际推进或实际恢复金额，且当前不需要立即再次运行。</li><li><code>partial</code>：本轮只完成了一部分，或暂时还没有恢复金额，但仍有资产处于等待或受限状态。</li><li><code>waiting_to_rerun</code>：本轮推进正常，但您仍需要等待一段时间后再次运行。</li><li><code>failed</code>：本轮因严重错误而中断。</li></ul>',12)])])}const m=t(o,[["render",r]]);export{p as __pageData,m as default};
